    30	            let bytes = self.client.get(url).send().await?.bytes().await?;
    31	            let response: InterestPage = serde_json::from_slice(&bytes)?;
    32	            if response.items.is_empty() {
    33	                break;
    34	            }
    35	            let fetched_at = Utc::now();
    36	            offset += response.items.len();
    37	            for source in response.items {
    38	                declarations.push(decode_declaration(source, fetched_at)?);
    39	            }
    40	            if offset >= response.total_results {
