    64	impl ExposedDataPipeline {
    65	    /// Returns the absolute path and key of the most recently modified run directory.
    66	    /// Equal timestamps use the greatest UUID. An absent or empty store returns `None`.
    67	    /// This operation does not create or change files.
    68	    ///
    69	    /// # Errors
    70	    /// Returns an error if ingestion storage cannot be read.
    71	    pub async fn latest_ingestion(
    72	        root: &Path,
    73	    ) -> Result<Option<(PathBuf, IngestionKey)>, EntitySearchPipelineError> {
    74	        let root = path::absolute(root).map_err(|e| read_error(root, e))?;
    75	        let mut entries = match fs::read_dir(&root).await {
    76	            Ok(entries) => entries,
    77	            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
    78	            Err(error) => return Err(read_error(&root, error)),
    79	        };
    80	        let mut latest: Option<(SystemTime, PathBuf, IngestionKey)> = None;
    81	        while let Some(entry) = entries
    82	            .next_entry()
    83	            .await
    84	            .map_err(|e| read_error(&root, e))?
    85	        {
    86	            let path = entry.path();
    87	            if !entry
    88	                .file_type()
    89	                .await
    90	                .map_err(|e| read_error(&path, e))?
    91	                .is_dir()
    92	            {
    93	                continue;
    94	            }
    95	            let Some(key) = entry
    96	                .file_name()
    97	                .to_str()
    98	                .and_then(|name| name.parse::<IngestionKey>().ok())
    99	            else {
   100	                continue;
   101	            };
   102	            let modified_at = entry
   103	                .metadata()
   104	                .await
   105	                .and_then(|metadata| metadata.modified())
   106	                .map_err(|e| read_error(&path, e))?;
   107	            if latest.as_ref().is_none_or(|(latest_time, _, latest_key)| {
   108	                (modified_at, key.uuid()) > (*latest_time, latest_key.uuid())
   109	            }) {
   110	                latest = Some((modified_at, path, key));
   111	            }
   112	        }
   113	        Ok(latest.map(|(_, path, key)| (path, key)))
   114	    }
   115	
   116	    /// Creates a new instance of [`ExposedDataPipeline`] with an [`IngestionKey`]
   117	    ///
   118	    /// # Errors
   119	    /// - if [`root`] cannot be parsed as absolute
   120	    /// - if required directories cannot be created
   121	    pub fn new_with_ingestion_key(
   122	        root: &PathBuf,
   123	        key: IngestionKey,
   124	    ) -> Result<Self, EntitySearchPipelineError> {
   125	        let root_abs = path::absolute(root).map_err(|_| {
   126	            EntitySearchPipelineError::Unexpected("valid root path must be provided".to_string())
   127	        })?;
   128	
   129	        let res = Self {
   130	            root: root_abs,
   131	            key: PipelineKey::from(key),
   132	            fs_schema: FsSchema::default(),
   133	        };
   134	        std::fs::create_dir_all(res.raw_path()).map_err(|_| {
   135	            EntitySearchPipelineError::Unexpected("must be able to create fs paths".to_string())
   136	        })?;
   137	        Ok(res)
   138	    }
